/* ---------- Segmented control ---------- */
/* one choice from a few views of the same thing: the picked one sits on a white knob that slides to it. It is a tab
   list, so the arrow keys move along it and the panel under it changes with it */
.sgc{width:100%;max-width:400px;margin:0 auto;padding:16px;display:flex;flex-direction:column;gap:14px}
.sgc-h{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}
.sgc-ht{display:flex;flex-direction:column;min-width:0}
.sgc-ht b{font-weight:500;font-size:14px}
.sgc-bar{display:flex;align-items:center;gap:2px;margin:-4px 0 -6px}
.sgc-r{flex:1;min-width:0;font-size:13px;color:var(--fg2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sgc-bar .ib{width:28px;height:28px}
.sgc-bar .pill{margin-right:4px}
.sgc-seg{position:relative;display:inline-flex;padding:3px;border-radius:var(--r-pill);background:var(--chip);flex:none}
.sgc-k{position:absolute;top:3px;bottom:3px;left:3px;width:0;border-radius:var(--r-pill);background:var(--surface);box-shadow:var(--shadow);transition:left .42s var(--ease),width .42s var(--ease)}
.sgc-seg button{position:relative;z-index:1;height:30px;padding:0 14px;border-radius:var(--r-pill);font-size:13px;color:var(--fg2);outline:0;transition:color .2s}
.sgc-seg button[aria-selected="true"],.sgc-seg button[aria-checked="true"]{color:var(--fg)}
@media (hover:hover) and (pointer:fine){.sgc-seg button:hover{color:var(--fg)}}
.sgc-seg button:focus-visible{box-shadow:0 0 0 2px var(--accent-mark,var(--accent))}
.sgc-p{height:178px;border-radius:12px;outline:0}
.sgc-p:focus-visible{box-shadow:0 0 0 2px var(--accent-bg)}
.sgc-in{height:100%;transition:opacity .16s,filter .16s,transform .2s var(--ease)}
.sgc-in.out{opacity:0;filter:blur(3px);transform:translateY(4px)}
/* the day: its events in order */
.sgc-day{display:flex;flex-direction:column;gap:6px}
.sgc-ev{display:flex;align-items:center;gap:12px;min-height:50px;padding:6px 12px;border-radius:12px;background:var(--row);font-size:13px}
.sgc-ev i{width:3px;align-self:stretch;margin:4px 0;border-radius:2px;background:var(--c);flex:none}
.sgc-ev .t{flex:1;min-width:0;display:flex;flex-direction:column}
.sgc-ev .t span{font-size:12px;color:var(--muted)}
.sgc-none{height:100%;display:grid;place-items:center;font-size:13px;color:var(--muted)}
/* the week: one row a day with its first event, a count of the rest, and today picked out */
.sgc-wk{display:flex;flex-direction:column;gap:2px}
.sgc-wr{display:flex;align-items:center;gap:10px;width:100%;height:23px;padding:0 8px;border-radius:8px;font-size:12.5px;text-align:left;transition:background var(--t-fast)}
@media (hover:hover) and (pointer:fine){.sgc-wr:hover{background:var(--row)}}
.sgc-wr:focus-visible,.sgc-mo .d:focus-visible{outline:0;box-shadow:0 0 0 2px var(--accent-mark,var(--accent))}
.sgc-wr .d{width:46px;flex:none;color:var(--muted)}
.sgc-wr .e{flex:1;min-width:0;display:flex;align-items:center;gap:8px;white-space:nowrap}
.sgc-wr .e i{width:6px;height:6px;border-radius:50%;background:var(--c);flex:none}
.sgc-wr .e .tm{color:var(--muted);flex:none}
.sgc-wr .e span:last-child{min-width:0;overflow:hidden;text-overflow:ellipsis}
.sgc-wr .more{flex:none;font-size:12px;color:var(--muted)}
.sgc-wr.none .e{color:var(--muted)}
.sgc-wr.now{background:var(--sel)}
@media (hover:hover) and (pointer:fine){.sgc-wr.now:hover{background:var(--sel)}}
.sgc-wr.now .d{color:var(--fg);font-weight:500}
/* the month: a dot on each day with something on */
.sgc-mo{display:grid;grid-template-columns:repeat(7,1fr);gap:2px 4px;font-size:12px;text-align:center}
.sgc-mo .w{font-size:11px;color:var(--muted);padding-bottom:2px}
.sgc-mo .d{position:relative;height:26px;display:grid;place-items:center;border-radius:8px;color:var(--fg2);transition:background var(--t-fast)}
.sgc-mo.r6 .d{height:22px}
@media (hover:hover) and (pointer:fine){.sgc-mo .d:hover{background:var(--row)}}
.sgc-mo .d.on{background:var(--chip);color:var(--fg)}
.sgc-mo .d.e::after{content:"";position:absolute;bottom:2px;left:50%;width:4px;height:4px;margin-left:-2px;border-radius:50%;background:var(--accent-mark,var(--accent))}
.sgc-mo .d.now{background:var(--ink);color:var(--on-ink)}
@media (hover:hover) and (pointer:fine){.sgc-mo .d.now:hover{background:var(--ink);color:var(--on-ink)}}
.sgc-mo .d.now::after{background:var(--on-ink)}

DM.def('segmented-control', (r, c) => {
  const uid = Math.random().toString(36).slice(2, 7);
  const seg = $('.sgc-seg', r), knob = $('.sgc-k', r), tabs = $$('[role="tab"]', seg), panel = $('.sgc-p', r), inner = $('.sgc-in', r), range = $('.sgc-r', r);
  tabs.forEach(t => { t.id = `sgc-${t.dataset.v}-${uid}`; t.setAttribute('aria-controls', 'sgc-p-' + uid); });
  panel.id = 'sgc-p-' + uid;
  // the pricing launch in October 2026, seen as a day, a week or a month. Today is Friday the 23rd
  const TODAY = new Date(2026, 9, 23, 12), DAY0 = 864e5;
  const at = (d, n) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n, 12), iso = d => d.toISOString().slice(0, 10);
  const same = (a, b) => iso(a) === iso(b);
  // launch week is written out; the days around it are drawn from the work that leads up to it and follows it
  const E = {
    '2026-10-19':[['10:00', 'Kickoff with Maya', 'Pricing v4 brief', 'var(--pl)'], ['15:00', 'Brief the agents', 'Build and copy agents', 'var(--pm)']],
    '2026-10-20':[['10:00', 'Wireframe review', 'Pricing v4, frames 1 to 6', 'var(--pl)'], ['11:30', 'Copy for the plan cards', 'Copy agent', 'var(--pt)'], ['14:00', 'Token audit', 'Build agent', 'var(--pm)']],
    '2026-10-21':[['11:00', 'Copy pass', 'Plan cards and FAQ', 'var(--pt)']],
    '2026-10-22':[['14:00', 'Design QA', 'Pricing v4, all frames', 'var(--pb)'], ['16:30', 'Fix contrast issues', 'Build agent', 'var(--pm)']],
    '2026-10-23':[['09:30', 'Pricing review with Maya', 'Pricing v4, frames 1 to 3', 'var(--pl)'], ['13:00', 'Export tokens to CSS', 'Build agent', 'var(--pm)'], ['16:00', 'Ship pricing v4', 'designme.studio/pricing', 'var(--pb)']],
    '2026-10-24':[], '2026-10-25':[]
  };
  const POOL = [['Design crit', 'Pricing frames', 'var(--pl)'], ['Token audit', 'Build agent', 'var(--pm)'], ['Copy pass', 'Plan cards', 'var(--pt)'], ['Stakeholder check-in', 'Weekly', 'var(--pb)'],
    ['User interviews', 'Three sessions', 'var(--pl)'], ['Conversion review', 'Trial to paid', 'var(--pb)'], ['Research synthesis', 'Notes and quotes', 'var(--pt)'], ['Fix review notes', 'Build agent', 'var(--pm)']];
  const TIMES = ['09:30', '10:00', '11:30', '13:00', '14:00', '15:30', '16:00'];
  function evs(d){
    const k = iso(d); if (E[k]) return E[k];
    const wd = d.getDay(); if (wd === 0 || wd === 6) return [];
    let h = Math.floor(d / DAY0) * 2654435761 >>> 0; const nx = m => { h = Math.imul(h ^ h >>> 15, 2246822519) >>> 0; return h % m; };
    const n = [0, 1, 1, 2, 2, 3][nx(6)], t = new Set(), out = [];
    while (t.size < n) t.add(TIMES[nx(TIMES.length)]);
    [...t].sort().forEach(tm => { const e = POOL[nx(POOL.length)]; out.push([tm, e[0], e[1], e[2]]); });
    return E[k] = out;
  }
  const mon = d => at(d, -((d.getDay() + 6) % 7));
  const mo = (d, o) => d.toLocaleDateString('en-US', o);
  const UNIT = { day:'day', week:'week', month:'month' };
  const V = {
    day:[d => mo(d, { weekday:'long', month:'short', day:'numeric' }), d => { const e = evs(d); return e.length ? `<div class="sgc-day">${e.map(([t, n, x, col]) => `<div class="sgc-ev" style="--c:${col}"><span class="num muted">${t}</span><i></i><span class="t">${n}<span>${x}</span></span></div>`).join('')}</div>` : '<div class="sgc-none">Nothing planned</div>'; }],
    week:[d => { const a = mon(d), b = at(a, 6); return mo(a, { month:'short', day:'numeric' }) + ' – ' + (a.getMonth() === b.getMonth() ? b.getDate() : mo(b, { month:'short', day:'numeric' })); },
      d => `<div class="sgc-wk">${Array.from({ length:7 }, (_, i) => at(mon(d), i)).map(x => { const ev = evs(x);
        return `<button class="sgc-wr${same(x, TODAY) ? ' now' : ''}${ev.length ? '' : ' none'}" data-d="${iso(x)}" aria-label="${mo(x, { weekday:'long', month:'long', day:'numeric' })}, ${ev.length ? ev.length + (ev.length === 1 ? ' event' : ' events') : 'nothing planned'}"><span class="d">${mo(x, { weekday:'short' })} ${x.getDate()}</span>${ev.length ? `<span class="e" style="--c:${ev[0][3]}"><i></i><span class="tm num">${ev[0][0]}</span><span>${ev[0][1]}</span></span>${ev.length > 1 ? `<span class="more">+${ev.length - 1} more</span>` : ''}` : '<span class="e">Nothing planned</span>'}</button>`; }).join('')}</div>`],
    month:[d => mo(d, { month:'long', year:'numeric' }), d => { const a = new Date(d.getFullYear(), d.getMonth(), 1, 12), lead = (a.getDay() + 6) % 7, len = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate();
      return `<div class="sgc-mo${lead + len > 35 ? ' r6' : ''}">${['M','T','W','T','F','S','S'].map(w => `<span class="w" aria-hidden="true">${w}</span>`).join('')}${'<span></span>'.repeat(lead)}${Array.from({ length:len }, (_, i) => { const x = at(a, i), n = evs(x).length;
        return `<button class="d num${n ? ' e' : ''}${same(x, TODAY) ? ' now' : ''}${same(x, sel) && !same(x, TODAY) ? ' on' : ''}" data-d="${iso(x)}" aria-label="${mo(x, { weekday:'long', month:'long', day:'numeric' })}, ${n ? n + (n === 1 ? ' event' : ' events') : 'nothing planned'}">${i + 1}</button>`; }).join('')}</div>`; }]
  };
  const pv = $('.sgc-pv', r), nxB = $('.sgc-nx', r), td = $('.sgc-td', r);
  // the knob slides to the picked tab and takes its width
  const place = () => { const t = tabs.find(x => x.getAttribute('aria-selected') === 'true'); knob.style.left = t.offsetLeft + 'px'; knob.style.width = t.offsetWidth + 'px'; };
  let cur = 'day', sel = TODAY, n = 0;
  // shows the view for the picked date: the range eases over and the panel fades through to the new dates
  function show(){
    const id = ++n, v = cur;
    swap(range, V[v][0](sel)); pv.setAttribute('aria-label', 'Previous ' + UNIT[v]); nxB.setAttribute('aria-label', 'Next ' + UNIT[v]);
    inner.classList.add('out');
    c.later(REDUCE ? 0 : 160, () => { if (id !== n) return; inner.innerHTML = V[v][1](sel); inner.classList.remove('out');
      // a day in the week or the month opens that day
      $$('[data-d]', inner).forEach(b => b.onclick = () => { const [y, m, dd] = b.dataset.d.split('-').map(Number); sel = new Date(y, m - 1, dd, 12); pick(tabs[0], false, true); }); });
  }
  function pick(t, focus, force){
    tabs.forEach(x => { const on = x === t; x.setAttribute('aria-selected', on); x.tabIndex = on ? 0 : -1; });
    panel.setAttribute('aria-labelledby', t.id); place();
    if (focus) t.focus({ preventScroll:true });
    if (t.dataset.v === cur && !force) return; cur = t.dataset.v; show();
  }
  // previous and next step by the view's unit; Today comes back to the 23rd
  const step = k => { sel = cur === 'day' ? at(sel, k) : cur === 'week' ? at(sel, 7 * k) : new Date(sel.getFullYear(), sel.getMonth() + k, 1, 12); show(); };
  pv.innerHTML = I('chev-l','xs'); nxB.innerHTML = I('chev-r','xs');
  pv.onclick = () => step(-1); nxB.onclick = () => step(1);
  td.onclick = () => { sel = TODAY; show(); };
  tabs.forEach(t => t.onclick = () => pick(t));
  // the arrow keys move along the tabs and pick as they go; Home and End jump to the ends
  seg.onkeydown = e => {
    const i = tabs.indexOf(document.activeElement); if (i < 0) return;
    const go = { ArrowRight:i + 1, ArrowLeft:i - 1, Home:0, End:tabs.length - 1 }[e.key]; if (go === undefined) return;
    e.preventDefault(); pick(tabs[(go + tabs.length) % tabs.length], true);
  };
  inner.innerHTML = V.day[1](sel); pick(tabs[0]);
  knob.style.transition = 'none'; requestAnimationFrame(() => { place(); requestAnimationFrame(() => { knob.style.transition = ''; }); });
  const ro = new ResizeObserver(place); ro.observe(seg); c.offs.push(() => ro.disconnect());
  // the preview's story: the week, then Tuesday opened from it, a step on to Wednesday, the month, and back to the week
  c.story(async s => {
    await s.beat(3);
    await s.tap(tabs[1]); s.away(); await s.beat(4);
    await s.tap($$('.sgc-wr', inner)[1]); s.away(); await s.beat(4);
    await s.tap(nxB); s.away(); await s.beat(3);
    await s.tap(tabs[2]); s.away(); await s.beat(4);
    await s.tap(tabs[1]); s.away(); await s.beat(3);
  });
});
